  // editor/style.ts
  function scrollBarTestFunc() {
    const scrollBarTest = document.body.appendChild(HTML.div(
      { style: "width:30px; height:30px; overflow: auto;" },
      HTML.div({ style: "width:100%; height:40px" })
    ));
    if (scrollBarTest.firstChild.clientWidth < 30) {
      document.documentElement.classList.add("has-classic-scrollbars");
    }
    document.body.removeChild(scrollBarTest);
  }
  if (document.body) {
    scrollBarTestFunc();
  } else {
    const observer = new MutationObserver(function() {
      if (document.body) {
        scrollBarTestFunc();
        observer.disconnect();
      }
    });
    observer.observe(document.documentElement, { childList: true });
  }
